#include <stdio.h>
int mulA = 0, mulB = 0;
int loopPow(int x, int n) {
    int i, r = 1;
    for (i = 0; i < n; i++, mulA++) r = r * x;
    return r;
}
int recPow(int x, int n) {
    int half;
    if (n == 0)
        return 1;
    half = recPow(x * x, n / 2);
    mulB += (n % 2 == 1) ? 2 : 1;
    return (n % 2 == 1) ? x * half : half;
}
int main(void) {
    int a = loopPow(3, 6), b = recPow(3, 6);
    printf("%d %d %d %d", a, b, mulA, mulB);
    return 0;
}

