#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n = 5, i, sum = 0;
    int *pi = (int *)malloc(n * sizeof(int));
    if (pi == NULL)
        return 1;
    for (i = 0; i < n; i++)
        pi[i] = (i + 1) * (i + 1);
    for (i = 1; i < n; i += 2)
        sum += *(pi + i);
    printf("%d %d", sum, pi[n - 1]);
    free(pi);
    return 0;
}

